// Supabase Edge Function: notify-student-email
//
// Sends a best-effort email to a student when a counselor takes an action on
// one of their appointments (approved / declined / conducted / rescheduled /
// note added / summoned). Called from counselor-appointments.html after the
// in-app `notifications` row is inserted.
//
// Emails are ONLY sent to students with a real, verified personal email:
//   * email_verified must be true (set after the verify-email OTP flow), and
//   * auth_email must not be the fake "username@colm.edu.ph" placeholder.
// Unverified students still get the in-app notification â€” they just don't get
// the email, since it couldn't be delivered to a nonexistent address anyway.
//
// Optional `note` is rendered as a "Note from the guidance office" line in the
// email body (used for approve/decline/reschedule notes to the student).
//
// Optional `slip` ({ date, time, rescheduled }) attaches the student's
// Parent/Guardian Visitation Slip as a PDF alongside the email â€” used when a
// visit is being scheduled/confirmed (summon/approve/reschedule). The slip is
// generated right here with pdf-lib (no browser involved) and carries a
// RESCHEDULED stamp when rescheduled is true.
//
// Uses the service-role key only to READ the student's own row (their email +
// slip fields), plus the Resend API for delivery. Deliberately does not accept
// a target email or slip data from the caller beyond the date/time/rescheduled
// triple â€” names come from the database, so the function can't be tricked into
// mailing or forging arbitrary addresses.
//
// Deploy with the Supabase CLI (set RESEND_API_KEY first):
//   supabase secrets set RESEND_API_KEY=<key>
//   supabase functions deploy notify-student-email
//
// SUPABASE_URL, SUPABASE_ANON_KEY, and SUPABASE_SERVICE_ROLE_KEY are provided
// automatically to every function; ALLOWED_ORIGINS is optional (see below).

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  PDFDocument,
  StandardFonts,
  rgb,
} from "https://esm.sh/pdf-lib@1.17.1";
// School letterhead images (base64 PNG) inlined so this function
// deploys as a single file — Supabase's dashboard deploy only uploads
// index.ts and can't resolve a ./letterhead.ts sibling import.
// Rebuild after changing images/school-header.png / school-footer.png:
//   $b = [IO.File]::ReadAllBytes('images/school-header.png'); [Convert]::ToBase64String($b)
const SCHOOL_HEADER_B64 = "";

const SCHOOL_FOOTER_B64 = "";


const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const RESEND_API_KEY = Deno.env.get("RESEND_API_KEY")!;
const SENDER =
  Deno.env.get("EMAIL_SENDER") || "COLM Guidance Portal <no-reply@colmguidance.org>";

// CORS origin allowlist (same pattern as create-staff-account).
// 1. Built-in defaults: localhost, 127.0.0.1, private LAN ranges, "null".
// 2. Extra origins via ALLOWED_ORIGINS secret (comma-separated, supports "*"
//    wildcard, e.g. "https://*.vercel.app,https://colmguidance.org").
const DEFAULT_ALLOWED_ORIGIN_PATTERN =
  /^https?:\/\/(?:(?:localhost|127\.0\.0\.1|10\.\d{1,3}\.\d{1,3}\.\d{1,3}|172\.(?:1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3})(:\d+)?)$/;

function isOriginAllowed(origin: string): boolean {
  if (origin === "null") return true;
  if (DEFAULT_ALLOWED_ORIGIN_PATTERN.test(origin)) return true;
  const extra = (Deno.env.get("ALLOWED_ORIGINS") || "")
    .split(",")
    .map((s: string) => s.trim())
    .filter(Boolean);
  return extra.some((pattern: string) => {
    const re = new RegExp(
      "^" + pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*") + "$"
    );
    return re.test(origin);
  });
}

function corsHeadersFor(req: Request): Record<string, string> {
  const origin = req.headers.get("Origin") || "";
  const headers: Record<string, string> = {
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    Vary: "Origin",
  };
  if (isOriginAllowed(origin)) headers["Access-Control-Allow-Origin"] = origin;
  return headers;
}

type VisitationSlip = {
  date?: string | null;
  time?: string | null;
  rescheduled?: boolean;
};

type NotifyRequest = {
  recipient_user_id: string;
  subject: string;
  concern?: string | null;
  note?: string | null;
  details?: string | null;
  portal_url?: string | null;
  slip?: VisitationSlip | null;
};

type InfoSheetAnswers = Record<string, string | number | null | undefined>;

function infoValue(answers: InfoSheetAnswers, key: string): string {
  const value = answers[key];
  return value === null || value === undefined ? "" : String(value).trim();
}

function parentAge(answers: InfoSheetAnswers, parentGuardian: string): string {
  const parent = parentGuardian.trim().toLowerCase();
  const candidates = [
    ["father_name", "father_age"],
    ["mother_name", "mother_age"],
    ["guardian_name", "guardian_age"],
  ];
  const match = candidates.find(([nameKey]) => infoValue(answers, nameKey).toLowerCase() === parent);
  if (match) return infoValue(answers, match[1]);
  return infoValue(answers, "guardian_age") || infoValue(answers, "father_age") || infoValue(answers, "mother_age");
}

function json(body: unknown, status: number, headers: Record<string, string>): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json", ...headers },
  });
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function buildEmail(
  firstName: string,
  subject: string,
  concern: string | null | undefined,
  note: string | null | undefined,
  details: string | null | undefined,
  portalUrl: string | null | undefined,
  hasSlip: boolean
): string {
  const name = escapeHtml(firstName || "there");
  const concernBlock = concern
    ? `<p><strong>Concern:</strong><br>${escapeHtml(concern)}</p>`
    : "";
  const noteBlock = note
    ? `<p><strong>Note from the guidance office:</strong><br>${escapeHtml(note)}</p>`
    : "";
  const detailBlock = details
    ? `<p><strong>Date and time:</strong><br>${escapeHtml(details)}</p>`
    : "";
  const link = portalUrl
    ? `<p><a href="${escapeHtml(portalUrl)}">View it in your student portal</a></p>`
    : "";
  const slipBlock = hasSlip
    ? `<p><strong>Visitation Slip:</strong> A copy of your Parent/Guardian's Visitation Slip is attached to this email.</p>`
    : "";
  return `
    <p>Warm greetings, ${name},</p>
    <p>${escapeHtml(subject)}.</p>
    ${slipBlock}
    ${concernBlock}
    ${noteBlock}
    ${detailBlock}
    ${link}
    <p>â€” <em>COLM Guidance Office</em></p>
  `.trim();
}

// ---------- Visitation slip PDF (pdf-lib, no browser) ----------

// Mirrors the on-screen printable slip (counselor-common.js
// openVisitationSlip): school letterhead bands top + bottom, the same
// form fields in the same order, the Action Taken checkbox grid, and the
// Data Privacy Act footer â€” so the emailed attachment looks like the
// printed Parent/Guardian's Visitation Slip, not a plain list.
//
// Images are embedded from the base64 copies in ./letterhead.ts because
// Edge Functions can't reach ../images at runtime.

type PdfFont = { widthOfTextAtSize(text: string, size: number): number };

const SLIP_PAGE_W = 612; // US Letter portrait, points
const SLIP_PAGE_H = 792;
const SLIP_MARGIN = 34;
const BLACK = rgb(0.07, 0.09, 0.15);
const RED = rgb(0.72, 0.11, 0.11);
const GRAY = rgb(0.35, 0.39, 0.45);

// Header/footer bands drawn full-bleed (width == page width), height scaled
// from each image's own aspect ratio.
const HEADER_H = SLIP_PAGE_W * (187 / 815); // school-header.png 815x187
const FOOTER_H = SLIP_PAGE_W * (100 / 835); // school-footer.png 835x100

function slipWrapLines(
  text: string,
  font: PdfFont,
  size: number,
  maxWidth: number
): string[] {
  const words = String(text || "")
    .split(/\s+/)
    .filter((w) => w.length > 0);
  if (!words.length) return [""];
  const lines: string[] = [];
  let line = "";
  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word;
    if (!line || font.widthOfTextAtSize(candidate, size) <= maxWidth) {
      line = candidate;
    } else {
      lines.push(line);
      line = word;
    }
  }
  if (line) lines.push(line);
  return lines;
}

function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

// Same contact-number formatting as the print slip (counselor-common.js
// ccFormatPhone): +63 XXX XXX XXXX.
function formatPhone(value: string): string {
  const raw = String(value ?? "").trim();
  let d = raw.replace(/\D/g, "");
  if (raw.startsWith("+63") || /^63[\s-]?9/.test(raw)) d = d.slice(2);
  else if (d.startsWith("09")) d = d.slice(1);
  d = d.slice(0, 10);
  if (!d) return "";
  let out = "+63";
  if (d.length > 0) out += " " + d.slice(0, 3);
  if (d.length > 3) out += " " + d.slice(3, 6);
  if (d.length > 6) out += " " + d.slice(6);
  return out;
}

async function buildVisitationSlipPdf(opts: {
  studentName: string;
  gradeSection: string;
  parentGuardian: string;
  parentAge: string;
  contactNumber: string;
  homeAddress: string;
  date: string;
  time: string;
  concern: string;
  rescheduled: boolean;
}): Promise<Uint8Array> {
  const pdfDoc = await PDFDocument.create();
  const page = pdfDoc.addPage([SLIP_PAGE_W, SLIP_PAGE_H]);
  const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const bold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  // School letterhead bands (same images as the printable slip).
  const headerImg = await pdfDoc.embedPng(b64ToBytes(SCHOOL_HEADER_B64));
  const footerImg = await pdfDoc.embedPng(b64ToBytes(SCHOOL_FOOTER_B64));
  page.drawImage(headerImg, { x: 0, y: SLIP_PAGE_H - HEADER_H, width: SLIP_PAGE_W, height: HEADER_H });
  page.drawImage(footerImg, { x: 0, y: 0, width: SLIP_PAGE_W, height: FOOTER_H });

// Layout mirrors the print slip's flexbox rows exactly: labels sit inline
  // and the underline fill grows to the row's right edge (paired fields share
  // the available width like flex:1), so all rows share the same left margin
  // and all fills terminate at the same right margin.
  const m = SLIP_MARGIN;
  const right = SLIP_PAGE_W - m;
  const contentW = right - m;
  const FIELD_SIZE = 12;
  const ROW_GAP = 34;

  // Truncate a value so it never spills past its underline (the print slip's
  // .fill has overflow:hidden, so overly long entries get cut the same way).
  const ellipsize = (text: string, maxW: number): string => {
    const t = String(text || "");
    if (bold.widthOfTextAtSize(t, FIELD_SIZE) <= maxW) return t;
    let out = t;
    while (out.length > 0 && bold.widthOfTextAtSize(out + "\u2026", FIELD_SIZE) > maxW) {
      out = out.slice(0, -1);
    }
    return out + "\u2026";
  };

  const labelWof = (label: string) => bold.widthOfTextAtSize(`${label}:`, FIELD_SIZE) + 9;

  // Vertical layout below the letterhead: title, then field rows.
  let y = SLIP_PAGE_H - HEADER_H - 28;

  const centerText = (text: string, size: number, f: PdfFont, color: unknown) => {
    const w = (f as PdfFont).widthOfTextAtSize(text, size);
    page.drawText(text, {
      x: (SLIP_PAGE_W - w) / 2,
      y,
      size,
      font: f as never,
      color: color as never,
    });
  };

  centerText("Parent/Guardian\u2019s Visitation Slip", 16, bold, BLACK);
  y -= 28;

  const drawUnderline = (fromX: number, width: number) => {
    page.drawLine({
      start: { x: fromX, y: y - 3 },
      end: { x: fromX + width, y: y - 3 },
      thickness: 0.9,
      color: BLACK as never,
    });
  };

  const drawLabel = (label: string, x: number) => {
    page.drawText(`${label}:`, { x, y, size: FIELD_SIZE, font: bold as never, color: BLACK as never });
    return x + labelWof(label);
  };

  // Row 1: Date | Time on the same line, RESCHEDULED stamp on the right
  // (mirrors the print slip's .resched-line).
  {
    const stampW = opts.rescheduled ? 150 : 0;
    const flexW = contentW - stampW - (opts.rescheduled ? 12 : 0);
    const colMid = m + flexW / 2;
    let dx = drawLabel("Date", m);
    drawUnderline(dx, colMid - 6 - dx);
    if (opts.date) page.drawText(ellipsize(opts.date, colMid - 6 - dx - 4), { x: dx + 3, y, size: FIELD_SIZE, font: font as never, color: BLACK as never });
    dx = drawLabel("Time", colMid);
    drawUnderline(dx, m + flexW - dx - 4);
    if (opts.time) page.drawText(ellipsize(opts.time, m + flexW - dx - 8), { x: dx + 3, y, size: FIELD_SIZE, font: font as never, color: BLACK as never });
    if (opts.rescheduled) {
      const stampText = "RESCHEDULED";
      page.drawRectangle({ x: right - stampW, y: y - 14, width: stampW, height: 22, borderColor: RED, borderWidth: 1.5 });
      const sw = bold.widthOfTextAtSize(stampText, 11);
      page.drawText(stampText, { x: right - stampW + (stampW - sw) / 2, y: y - 8, size: 11, font: bold as never, color: RED as never });
    }
    y -= ROW_GAP;
  }

  // Rows 3 and 5 pair a "grow2" label (wide fill) with a smaller one, like
  // .fill.grow2 flex:2.2 — the wide fill takes ~2.2x the narrow one's share.
  const growPairRow = (left: [string, string], rightF: [string, string], wideRatio = 2.2) => {
    let dx = drawLabel(left[0], m);
    const rightLabelGap = 10;
    const flexW = contentW - labelWof(rightF[0]) - rightLabelGap;
    const leftFill = (flexW - dx) * (wideRatio / (wideRatio + 1));
    drawUnderline(dx, leftFill);
    if (left[1]) page.drawText(ellipsize(left[1], leftFill - 4), { x: dx + 3, y, size: FIELD_SIZE, font: font as never, color: BLACK as never });
    dx = drawLabel(rightF[0], dx + leftFill + rightLabelGap);
    drawUnderline(dx, contentW - (dx - m));
    if (rightF[1]) page.drawText(ellipsize(rightF[1], contentW - (dx - m) - 4), { x: dx + 3, y, size: FIELD_SIZE, font: font as never, color: BLACK as never });
    y -= ROW_GAP;
  };

  // Name of Mother/Father/Guardian (grow2) | Age (fixed short fill, like
  // .fill.fixed width:120px).
  {
    const ageFill = 90;
    const gap = 10;
    let dx = drawLabel("Name of Mother/Father/Guardian", m);
    const parentFill = right - dx - (labelWof("Age") + gap + ageFill);
    drawUnderline(dx, parentFill);
    if (opts.parentGuardian) page.drawText(ellipsize(opts.parentGuardian, parentFill - 4), { x: dx + 3, y, size: FIELD_SIZE, font: font as never, color: BLACK as never });
    dx = drawLabel("Age", right - labelWof("Age") - gap - ageFill);
    drawUnderline(dx, ageFill);
    if (opts.parentAge) page.drawText(ellipsize(opts.parentAge, ageFill - 4), { x: dx + 3, y, size: FIELD_SIZE, font: font as never, color: BLACK as never });
    y -= ROW_GAP;
  }

  const singleRow = (label: string, value?: string, rowGap = ROW_GAP) => {
    let dx = drawLabel(label, m);
    drawUnderline(dx, contentW - (dx - m) - 4);
    if (value) page.drawText(ellipsize(value, contentW - (dx - m) - 8), { x: dx + 3, y, size: FIELD_SIZE, font: font as never, color: BLACK as never });
    y -= rowGap;
  };

  singleRow("Contact No.", opts.contactNumber);
  singleRow("Home Address", opts.homeAddress);
  growPairRow(["Name of son/daughter", opts.studentName], ["Grade-Section", opts.gradeSection]);
  singleRow("Child\u2019s Class Adviser");

  // Keep both conference fields on one compact line, with each label and
  // underline occupying its own half of the available width.
  {
    const columnGap = 12;
    const columnW = (contentW - columnGap) / 2;
    const labels = ["Number of Conference with the Class Adviser", "Date of Last Conference"];
    labels.forEach((label, index) => {
      const x = m + index * (columnW + columnGap);
      const labelSize = 9.5;
      const labelW = bold.widthOfTextAtSize(`${label}:`, labelSize) + 5;
      page.drawText(`${label}:`, { x, y, size: labelSize, font: bold as never, color: BLACK as never });
      page.drawLine({
        start: { x: x + labelW, y: y - 3 },
        end: { x: x + columnW, y: y - 3 },
        thickness: 0.9,
        color: BLACK as never,
      });
    });
    y -= ROW_GAP;
  }

  // Reason for Visit — bordered box with a min height, like the print slip's
  // .reason-box { min-height:66px }.
  page.drawText("Reason for Visit:", { x: m, y, size: FIELD_SIZE, font: bold as never, color: BLACK as never });
  y -= 20;
  const reasonLines = slipWrapLines(opts.concern, font, FIELD_SIZE, contentW - 16);
  const reasonLineH = 16;
  const boxH = Math.max(64, reasonLines.length * reasonLineH + 12);
  const boxBottom = y - boxH;
  reasonLines.forEach((line, i) => {
    page.drawText(line, { x: m + 8, y: boxBottom + boxH - 18 - i * reasonLineH, size: FIELD_SIZE, font: font as never, color: BLACK as never });
  });
  page.drawRectangle({ x: m, y: boxBottom, width: contentW, height: boxH, borderColor: BLACK, borderWidth: 1 });
  y = boxBottom - 20;

  // Action Taken — same checkbox grid as the print slip (2 columns, same
  // item order: class adviser & concerned teacher first, then JHS/SHS
  // Coordinators, then Discipline Officer / Registered Guidance Personnel).
  const actions = [
    "referral to the class adviser",
    "referral to the concerned teacher",
    "referral to the JHS Coordinator",
    "referral to the SHS Coordinator",
    "referral to the Discipline Officer",
    "referral to Registered Guidance Personnel",
  ];
  page.drawText("Action Taken:", { x: m, y, size: FIELD_SIZE, font: bold as never, color: BLACK as never });
  y -= 20;
  const cbSize = 8.5;
  const actionColGap = 21;
  const actionColW = (contentW - actionColGap) / 2;
  const actionRowH = 25;
  actions.forEach((a, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = m + col * (actionColW + actionColGap);
    const yy = y - row * actionRowH;
    page.drawRectangle({ x, y: yy - 1, width: cbSize, height: cbSize, borderColor: BLACK, borderWidth: 1 });
    page.drawText(a, { x: x + cbSize + 6, y: yy, size: 12, font: font as never, color: BLACK as never });
  });
  y -= Math.ceil(actions.length / 2) * actionRowH + 18;

  // Data Privacy Act footer text (mirrors .privacy on the print slip).
  const privacy =
    "Data Privacy Act: All data gathered will be kept confidential in compliance with Republic Act 10173 otherwise known as the Data Privacy Act of 2012 and shall only be used for school record purposes and shall be accessed only by authorized school personnel.";
  const pLines = slipWrapLines(privacy, font, 9.5, contentW);
  const privacyLineH = 10;
  const privacyBottomY = Math.max(FOOTER_H + 8, y - 8);
  const privacyStartY = privacyBottomY + (pLines.length - 1) * privacyLineH;
  pLines.forEach((line, i) => {
    page.drawText(line, {
      x: m,
      y: privacyStartY - i * privacyLineH,
      size: 8.5,
      font: font as never,
      color: GRAY as never,
    });
  });

  return pdfDoc.save();
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

Deno.serve(async (req) => {
  const headers = corsHeadersFor(req);

  if (req.method === "OPTIONS") {
    return new Response("ok", { headers });
  }

  try {
    const body = (await req.json()) as NotifyRequest;

    if (!body?.recipient_user_id || !body?.subject) {
      return json({ error: "recipient_user_id and subject are required." }, 400, headers);
    }
    if (!RESEND_API_KEY) {
      return json({ error: "RESEND_API_KEY is not configured." }, 500, headers);
    }

    const supabase = createClient(SUPABASE_URL, SERVICE_ROLE_KEY);
    const { data: student } = await supabase
      .from("students")
      .select(
        "student_id, first_name, last_name, year_level, section, parent_guardian, contact_number, auth_email, email_verified"
      )
      .eq("user_id", body.recipient_user_id)
      .maybeSingle();

    if (!student?.auth_email) {
      return json({ ok: true, skipped: "no student row" }, 200, headers);
    }
    if (student.email_verified !== true) {
      return json({ ok: true, skipped: "email not verified" }, 200, headers);
    }
    if (/@colm\.edu\.ph$/i.test(student.auth_email)) {
      return json({ ok: true, skipped: "placeholder email" }, 200, headers);
    }

    // Attach the visitation slip PDF when a visit is being scheduled â€”
    // best-effort: if the PDF can't be generated the email still goes out,
    // but the skip reason is reported back so the counselor knows the slip
    // was NOT attached (a silent no-attachment is how this feature broke).
    let attachment: unknown = null;
    let hasSlip = false;
    let slipError: string | null = null;
    if (body.slip) {
      try {
        const { data: infoSheet, error: infoSheetError } = await supabase
          .from("student_info_sheets")
          .select("answers")
          .eq("student_id", student.student_id)
          .eq("status", "submitted")
          .order("submitted_at", { ascending: false })
          .limit(1)
          .maybeSingle();
        if (infoSheetError) console.error("Student info sheet lookup failed:", infoSheetError);
        const answers = (infoSheet?.answers || {}) as InfoSheetAnswers;
        const parentGuardian = student.parent_guardian || infoValue(answers, "guardian_name");
        const pdfBytes = await buildVisitationSlipPdf({
          studentName: `${student.first_name} ${student.last_name}`.trim(),
          gradeSection: [student.year_level, student.section].filter(Boolean).join(" \u2013 "),
          parentGuardian,
          parentAge: parentAge(answers, parentGuardian),
          contactNumber: formatPhone(student.contact_number || infoValue(answers, "contact")),
          homeAddress: infoValue(answers, "address"),
          date: body.slip.date || "",
          time: body.slip.time || "",
          concern: body.concern || "",
          rescheduled: body.slip.rescheduled === true,
        });
        attachment = {
          filename: "Visitation-Slip.pdf",
          content: bytesToBase64(pdfBytes),
          type: "application/pdf",
        };
        hasSlip = true;
      } catch (slipErr) {
        slipError = slipErr instanceof Error ? slipErr.message : String(slipErr);
        console.error("Visitation slip PDF generation failed:", slipErr);
      }
    }

    const resPayload: Record<string, unknown> = {
      from: SENDER,
      to: [student.auth_email],
      subject: body.subject,
      html: buildEmail(
        student.first_name,
        body.subject,
        body.concern,
        body.note,
        body.details,
        body.portal_url,
        hasSlip
      ),
    };
    if (attachment) resPayload.attachments = [attachment];

    const res = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${RESEND_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(resPayload),
    });

    if (!res.ok) {
      const detail = await res.text();
      return json({ error: `Resend rejected the email: ${detail}` }, 502, headers);
    }

    return json(
      slipError
        ? { ok: true, slipAttached: hasSlip, slipError, warned: "slip PDF failed to build; emailed without attachment" }
        : { ok: true, slipAttached: hasSlip },
      200,
      headers
    );
  } catch (err) {
    return json({ error: err.message || "Unexpected error." }, 500, headers);
  }
});